/**
 * Signs release builds with the private Smaran key when it is provided.
 *
 * `android/` is generated by prebuild and not committed, so the signing setup
 * has to be re-applied on every prebuild -- hence a config plugin rather than a
 * hand edit to build.gradle.
 *
 * The key is read from Gradle properties, never from the repo:
 *   SMARAN_UPLOAD_STORE_FILE      absolute path to the .jks
 *   SMARAN_UPLOAD_STORE_PASSWORD
 *   SMARAN_UPLOAD_KEY_ALIAS
 *   SMARAN_UPLOAD_KEY_PASSWORD
 * CI passes them as ORG_GRADLE_PROJECT_* env vars; locally they can live in
 * ~/.gradle/gradle.properties. Without them, release falls back to the debug
 * key -- such an APK cannot update an installed CI build.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// smaran-release-signing';

const RELEASE_SIGNING_CONFIG = `
        ${MARKER}
        release {
            if (findProperty('SMARAN_UPLOAD_STORE_FILE')) {
                storeFile file(findProperty('SMARAN_UPLOAD_STORE_FILE'))
                storePassword findProperty('SMARAN_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('SMARAN_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('SMARAN_UPLOAD_KEY_PASSWORD')
            }
        }`;

function applySigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  const withConfig = gradle.replace(/signingConfigs\s*\{/, match => `${match}${RELEASE_SIGNING_CONFIG}`);
  if (withConfig === gradle) {
    throw new Error('withReleaseSigning: could not find signingConfigs in app/build.gradle');
  }

  // Only the release build type's signing line changes; debug keeps the debug key.
  const buildTypesAt = withConfig.indexOf('buildTypes');
  const head = withConfig.slice(0, buildTypesAt);
  const tail = withConfig.slice(buildTypesAt);
  const patchedTail = tail.replace(
    /(release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
    "$1signingConfig findProperty('SMARAN_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug"
  );
  if (patchedTail === tail) {
    throw new Error('withReleaseSigning: could not find the release signingConfig in app/build.gradle');
  }

  return head + patchedTail;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, mod => {
    mod.modResults.contents = applySigning(mod.modResults.contents);
    return mod;
  });
};
